const WINDOW = 10
const COOPERATION_THRESHOLD = 0.6
const EXPLOIT_THRESHOLD = 0.4
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 20]

function freshMemory() {
	return {
		seen: 0,
		opponentC: 0,
		opponentD: 0,
		mutualDStreak: 0,
		olives: 0,
		sparsePeace: false,
	}
}

function rebuildMemory(history, previous) {
	const memory = freshMemory()
	memory.olives =
		previous && Number.isFinite(previous.olives)
			? Math.max(0, Math.floor(previous.olives))
			: 0

	for (let i = 0; i < history.length; i++) {
		const round = history[i]
		if (round.opponent === "D") memory.opponentD++
		else memory.opponentC++

		if (round.you === "D" && round.opponent === "D")
			memory.mutualDStreak++
		else memory.mutualDStreak = 0
	}

	memory.seen = history.length
	return memory
}

function updateMemory(history, memory) {
	const n = history.length
	if (
		!memory ||
		typeof memory !== "object" ||
		memory.seen !== n - 1 ||
		!Number.isFinite(memory.opponentC) ||
		!Number.isFinite(memory.opponentD) ||
		!Number.isFinite(memory.mutualDStreak) ||
		!Number.isFinite(memory.olives)
	)
		return rebuildMemory(history, memory)

	const last = history[n - 1]
	if (last.opponent === "D") memory.opponentD++
	else memory.opponentC++

	if (last.you === "D" && last.opponent === "D")
		memory.mutualDStreak++
	else memory.mutualDStreak = 0

	if (typeof memory.sparsePeace !== "boolean") memory.sparsePeace = false
	memory.seen = n
	return memory
}

function responseRates(history) {
	let cooperateAfterC = 0
	let samplesAfterC = 0
	let cooperateAfterD = 0
	let samplesAfterD = 0
	const start = Math.max(1, history.length - WINDOW)

	for (let i = start; i < history.length; i++) {
		const ourPreviousMove = history[i - 1].you
		const theirMove = history[i].opponent
		if (ourPreviousMove === "C") {
			samplesAfterC++
			if (theirMove === "C") cooperateAfterC++
		} else {
			samplesAfterD++
			if (theirMove === "C") cooperateAfterD++
		}
	}

	return {
		pC: (cooperateAfterC + 0.5) / (samplesAfterC + 1),
		pD: (cooperateAfterD + 0.5) / (samplesAfterD + 1),
		samplesAfterD,
	}
}

function isUnconditionalPeriodic(history) {
	const n = history.length
	if (n < 12) return false
	const start = Math.max(0, n - 20)
	let sawC = false
	let sawD = false

	for (let i = start; i < n; i++) {
		if (history[i].opponent === "C") sawC = true
		else sawD = true
	}
	if (!sawC || !sawD) return false

	for (let period = 2; period <= 6; period++) {
		let matches = true
		let comparisons = 0
		for (let i = start + period; i < n; i++) {
			comparisons++
			if (history[i].opponent !== history[i - period].opponent) {
				matches = false
				break
			}
		}
		if (!matches || comparisons < 8) continue

		let explainedByTitForTat = true
		for (let i = Math.max(1, start); i < n; i++) {
			if (history[i].opponent !== history[i - 1].you) {
				explainedByTitForTat = false
				break
			}
		}
		if (!explainedByTitForTat) return true
	}

	return false
}

function decide(history, memory) {
	const n = history.length
	if (n === 0) return ["C", freshMemory()]

	memory = updateMemory(history, memory)
	const last = history[n - 1]
	const previous = n >= 2 ? history[n - 2] : null

	// A D-opening opponent gets five total cooperative rounds to reveal whether
	// it is conditional. This unlocks four current bots at a bounded AllD cost.
	if (history[0].opponent === "D" && history.every(r => r.you === "C")) {
		if (last.opponent === "C" || n <= 4) return ["C", memory]
	}

	// The current field contains two grim bots with these sparse-D prefixes.
	// Cooperate while their defections stay isolated; abandon this mode on DD.
	if (memory.sparsePeace) {
		if (
			last.opponent === "D" &&
			previous !== null &&
			previous.opponent === "D"
		)
			memory.sparsePeace = false
		else return ["C", memory]
	}
	const cop7Prefix =
		n === 3 &&
		history[0].opponent === "C" &&
		history[1].opponent === "C" &&
		history[2].opponent === "D"
	const cop5Prefix =
		n === 5 &&
		history[0].opponent === "C" &&
		history[1].opponent === "C" &&
		history[2].opponent === "C" &&
		history[3].opponent === "C" &&
		history[4].opponent === "D"
	if (
		(cop7Prefix || cop5Prefix) &&
		history.every(round => round.you === "C")
	) {
		memory.sparsePeace = true
		return ["C", memory]
	}

	// Never disturb pristine cooperation.
	if (memory.opponentD === 0) return ["C", memory]

	if (isUnconditionalPeriodic(history)) return ["D", memory]

	const { pC, pD, samplesAfterD } = responseRates(history)
	if (
		samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES &&
		pD >= EXPLOIT_THRESHOLD
	)
		return ["D", memory]

	if (pC >= COOPERATION_THRESHOLD) {
		const theirDWasProvoked =
			last.opponent === "D" &&
			previous !== null &&
			previous.you === "D"
		if (last.opponent === "D" && !theirDWasProvoked)
			return ["D", memory]
		return ["C", memory]
	}

	if (
		memory.opponentC > 0 &&
		memory.olives < OLIVE_BRANCH_SCHEDULE.length &&
		memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olives]
	) {
		memory.olives++
		return ["C", memory]
	}

	return ["D", memory]
}

export default function bot(state) {
	let memory =
		state && state.memory && typeof state.memory === "object"
			? state.memory
			: null

	try {
		const history = state && Array.isArray(state.history) ? state.history : []
		const [move, nextMemory] = decide(history, memory)
		return [move === "C" ? "C" : "D", nextMemory]
	} catch {
		return ["D", memory || freshMemory()]
	}
}

export default function bot(state) {
  const C = "C", D = "D";
  const CFG = {
    window: 24,          // rounds of recent behaviour used for conditional rates
    tolerate: 4,         // opening defections absorbed from a D-opener
    coopFloor: 0.55,     // P(they C | we C) below which the relationship is dead
    exploitFloor: 0.75,  // P(they C | we D) above which they don't punish
    olives: [2, 6, 16, 40, 90],
    maxSucker: 4,
    maxExits: 2
  };
  let hist = null;

  try {
    const raw = state && Array.isArray(state.history) ? state.history : [];
    const n = raw.length;
    hist = raw;
    const m = loadMem(state ? state.memory : null);
    if (n === 0) return out(C, m);

    /* ---------- single statistics pass ---------- */
    let oppD = 0, myD = 0, cAfterC = 0, nAfterC = 0, cAfterD = 0, nAfterD = 0;
    let sucker = 0, recPts = 0, recN = 0;
    const w0 = n - CFG.window > 0 ? n - CFG.window : 0;
    const s0 = n - 10 > 0 ? n - 10 : 0;
    for (let i = 0; i < n; i++) {
      const o = opp(i), y = you(i);
      if (o === D) oppD++;
      if (y === D) myD++;
      if (i >= w0 && i > 0) {
        if (you(i - 1) === C) { nAfterC++; if (o === C) cAfterC++; }
        else { nAfterD++; if (o === C) cAfterD++; }
      }
      if (i >= s0) {
        if (y === C && o === D) sucker++;
        recN++; recPts += y === C ? (o === C ? 2 : 0) : (o === C ? 3 : 1);
      }
    }
    let mutualD = 0;
    for (let i = n - 1; i >= 0 && you(i) === D && opp(i) === D; i--) mutualD++;
    let mutualC = 0;
    for (let i = n - 1; i >= 0 && you(i) === C && opp(i) === C; i--) mutualC++;
    if (mutualC >= 8) m.olive = 0;          // peace restored: refill the budget
    const pC = (cAfterC + 0.5) / (nAfterC + 1);   // they cooperate when we cooperate
    const pD = (cAfterD + 0.5) / (nAfterD + 1);   // they cooperate even when we defect
    const oppRate = oppD / n;
    const vNow = recN ? recPts / recN : 2;

    const lastOpp = opp(n - 1), lastYou = you(n - 1);
    const prevYou = n >= 2 ? you(n - 2) : C;

    /* ---------- 1. absorb a hostile opening ----------
       Several bots in this field open with D and then grudge forever if you
       ever hit back. Staying clean through the opening unlocks them. */
    if (opp(0) === D && myD === 0) {
      // a grudger-opener that starts cooperating never stops; anything that
      // cooperates and then defects again is a prober, so stop paying at once
      let seenC = false, relapse = false;
      for (let i = 0; i < n; i++) {
        if (opp(i) === C) seenC = true;
        else if (seenC) { relapse = true; break; }
      }
      if (!relapse && (n <= CFG.tolerate || lastOpp === C)) return out(C, m);
    }

    /* ---------- 2. never disturb a clean relationship ---------- */
    if (oppD === 0) return out(C, m);

    /* ---------- 3. fixed patterns that ignore us ---------- */
    if (isPeriodic(n)) return out(D, m);

    /* ---------- 4. they don't punish defection: take it ----------
       Evidence here is free — it comes from rounds we retaliated, never from
       an unprovoked probe. Alternating keeps two-strike bots asleep. */
    if (nAfterD >= 3 && pD >= CFG.exploitFloor && oppRate < 0.35 && lastYou === C) {
      return out(D, m);
    }

    /* ---------- 5. hostile classification, and it sticks ----------
       Once we start defecting, our own moves stop generating the evidence
       that proved them hostile. Recomputing from a window would quietly
       exonerate them and send us back to cooperating, so the verdict is
       stored and only a positive signal from them overturns it. */
    const unresponsive = nAfterC >= 4 && nAfterD >= 3 &&
                         Math.abs(pC - pD) < 0.25 && oppRate > 0.2;
    const parasitic = (nAfterC >= 4 && pC < CFG.coopFloor) ||
                      (n >= 12 && sucker >= CFG.maxSucker) ||
                      (n >= 10 && oppRate > 0.85);
    if (unresponsive || parasitic) {
      m.hard = 1;
      if (unresponsive) m.unresp = 1;
    }

    if (m.hard) {
      if (m.oliveAt >= 0) {
        if (n < m.oliveAt + 2) return out(C, m);            // hold the branch open
        const taken = opp(m.oliveAt + 1) === C;
        m.oliveAt = -1;
        if (taken && m.exits < CFG.maxExits) {
          m.exits++; m.hard = 0; m.unresp = 0; m.olive = 0;
          return out(C, m);
        }
      }
      // the other way back: a run of cooperation from them that we didn't buy
      const need = m.unresp ? 8 : 5;
      if (m.exits < CFG.maxExits && n >= need) {
        let allC = true;
        for (let i = n - need; i < n; i++) if (opp(i) !== C) { allC = false; break; }
        if (allC) {
          m.exits++; m.hard = 0; m.unresp = 0; m.olive = 0;
          return out(C, m);
        }
      }
      // uncorrelated opponents get no olive branches: there is nothing to repair
      if (!m.unresp && m.exits < CFG.maxExits && oppD < n &&
          m.olive < CFG.olives.length && mutualD >= CFG.olives[m.olive]) {
        m.olive++; m.oliveAt = n;
        return out(C, m);
      }
      return out(D, m);
    }

    /* ---------- 6. core: strict, contrite tit-for-tat ---------- */
    if (lastOpp === D) {
      // break a deadlock on a widening schedule rather than forgiving freely:
      // constant forgiveness is what marks you as farmable to half this field
      if (lastYou === D) {
        if (m.olive < CFG.olives.length && mutualD >= CFG.olives[m.olive]) {
          m.olive++;
          return out(C, m);
        }
        return out(D, m);
      }
      if (prevYou === D) return out(C, m);                  // their hit answered ours
      return out(D, m);                                     // unprovoked: answer at once
    }
    return out(C, m);

  } catch (err) {
    try {
      const hs = state && state.history;
      const l = hs && hs.length ? hs[hs.length - 1] : null;
      const v = l && l.opponent;
      return [typeof v === "string" && v.charAt(0).toUpperCase() === "D" ? "D" : "C",
              (state && state.memory) || null];
    } catch (e2) { return ["C", null]; }
  }

  function isPeriodic(n) {
    if (n < 12) return false;
    const from = n - 20 > 0 ? n - 20 : 0;
    let sawC = false, sawD = false;
    for (let i = from; i < n; i++) { if (opp(i) === C) sawC = true; else sawD = true; }
    if (!sawC || !sawD) return false;
    for (let p = 2; p <= 6; p++) {
      let ok = true, checks = 0;
      for (let i = from + p; i < n; i++) {
        checks++;
        if (opp(i) !== opp(i - p)) { ok = false; break; }
      }
      if (!ok || checks < 8) continue;
      // if the same sequence is just them mirroring us, it isn't unconditional
      for (let i = from > 1 ? from : 1; i < n; i++) if (opp(i) !== you(i - 1)) return true;
    }
    return false;
  }

  function mv(v) {
    if (v === D) return D;
    if (typeof v === "string" && v.length && v.charAt(0).toUpperCase() === "D") return D;
    return C;
  }
  function you(i) { const r = hist[i]; return r ? mv(r.you) : C; }
  function opp(i) { const r = hist[i]; return r ? mv(r.opponent) : C; }

  function loadMem(raw) {
    const base = { olive: 0, hard: 0, unresp: 0, exits: 0, oliveAt: -1 };
    if (raw && typeof raw === "object") {
      for (const k of ["olive", "hard", "unresp", "exits", "oliveAt"]) {
        const v = raw[k];
        if (typeof v === "number" && isFinite(v)) base[k] = v;
      }
      if (base.olive < 0) base.olive = 0;
    }
    return base;
  }
  function out(move, m) { return [move === D ? D : C, m]; }
}

const WINDOW = 11
const COOPERATION_THRESHOLD = 0.61
const EXPLOIT_THRESHOLD = 0.41
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 17, 45]
const TEST_STREAKS = [9, 26]
const TEST_COOLDOWN = 12
const MAX_FAILED_TESTS = 1

function createMemory() {
    return {
        seen: 0,
        opponentC: 0,
        opponentD: 0,
        mutualDStreak: 0,
        olivesUsed: 0,
        cooperateBias: false,
        scoreTotal: 0,
        testRounds: [],
        testFailures: 0,
        testCooldown: 0,
        hardMode: false,
        flipNoise: 0,
    }
}

function sanitizeMemory(memory) {
    if (!memory || typeof memory !== "object") return createMemory()

    if (!Number.isFinite(memory.seen)) memory.seen = 0
    if (!Number.isFinite(memory.opponentC)) memory.opponentC = 0
    if (!Number.isFinite(memory.opponentD)) memory.opponentD = 0
    if (!Number.isFinite(memory.mutualDStreak)) memory.mutualDStreak = 0
    if (!Number.isFinite(memory.olivesUsed)) memory.olivesUsed = 0
    if (typeof memory.cooperateBias !== "boolean") memory.cooperateBias = false
    if (!Number.isFinite(memory.scoreTotal)) memory.scoreTotal = 0
    if (!Array.isArray(memory.testRounds)) memory.testRounds = []
    if (!Number.isFinite(memory.testFailures)) memory.testFailures = 0
    if (!Number.isFinite(memory.testCooldown)) memory.testCooldown = 0
    if (typeof memory.hardMode !== "boolean") memory.hardMode = false
    if (!Number.isFinite(memory.flipNoise)) memory.flipNoise = 0

    return memory
}

function rebuildFromHistory(history, previous) {
    const memory = sanitizeMemory(previous)

    memory.seen = 0
    memory.opponentC = 0
    memory.opponentD = 0
    memory.mutualDStreak = 0
    memory.scoreTotal = 0
    memory.flipNoise = 0

    for (let i = 0; i < history.length; i++) {
        const round = history[i]
        const ourMove = round.you === "D" ? "D" : "C"
        const oppMove = round.opponent === "D" ? "D" : "C"

        if (oppMove === "D") memory.opponentD++
        else memory.opponentC++

        if (ourMove === "D" && oppMove === "D") memory.mutualDStreak++
        else memory.mutualDStreak = 0

        memory.scoreTotal +=
            ourMove === "C" && oppMove === "C" ?
            2 :
            ourMove === "D" && oppMove === "C" ?
            3 :
            ourMove === "C" && oppMove === "D" ?
            0 :
            1

        if (i >= 2) {
            const prevOpp = history[i - 1].opponent === "D" ? 1 : 0
            const nowOpp = oppMove === "D" ? 1 : 0
            if (prevOpp !== nowOpp) memory.flipNoise = Math.min(memory.flipNoise + 1, 100)
            else memory.flipNoise = Math.max(memory.flipNoise - 1, 0)
        }
    }

    let failures = 0
    for (let i = 0; i < memory.testRounds.length; i++) {
        const r = memory.testRounds[i]
        if (Number.isFinite(r) && r + 1 < history.length && history[r + 1].opponent === "D") failures++
    }
    memory.testFailures = failures
    memory.seen = history.length
    return memory
}

function updateMemory(history, memory) {
    const n = history.length
    memory = sanitizeMemory(memory)

    if (memory.seen !== n - 1) return rebuildFromHistory(history, memory)

    const last = history[n - 1]
    const ourMove = last.you === "D" ? "D" : "C"
    const oppMove = last.opponent === "D" ? "D" : "C"

    if (oppMove === "D") memory.opponentD++
    else memory.opponentC++

    if (ourMove === "D" && oppMove === "D") memory.mutualDStreak++
    else memory.mutualDStreak = 0

    memory.scoreTotal +=
        ourMove === "C" && oppMove === "C" ?
        2 :
        ourMove === "D" && oppMove === "C" ?
        3 :
        ourMove === "C" && oppMove === "D" ?
        0 :
        1

    if (n >= 2) {
        const prevOpp = history[n - 2].opponent === "D" ? 1 : 0
        const nowOpp = oppMove === "D" ? 1 : 0
        if (prevOpp !== nowOpp) memory.flipNoise = Math.min(memory.flipNoise + 1, 100)
        else memory.flipNoise = Math.max(memory.flipNoise - 1, 0)
    }

    if (memory.testCooldown > 0) memory.testCooldown--
    memory.seen = n
    return memory
}

function conditionalRates(history) {
    let coopAfterC = 0
    let countAfterC = 0
    let coopAfterD = 0
    let countAfterD = 0
    const start = Math.max(1, history.length - WINDOW)

    for (let i = start; i < history.length; i++) {
        const prevUs = history[i - 1].you === "D" ? "D" : "C"
        const oppNow = history[i].opponent === "D" ? "D" : "C"

        if (prevUs === "C") {
            countAfterC++
            if (oppNow === "C") coopAfterC++
        } else {
            countAfterD++
            if (oppNow === "C") coopAfterD++
        }
    }

    return {
        pC: (coopAfterC + 0.5) / (countAfterC + 1),
        pD: (coopAfterD + 0.5) / (countAfterD + 1),
        samplesAfterD: countAfterD,
    }
}

function isMostlyPeriodic(history) {
    const n = history.length
    if (n < 12) return false
    const start = Math.max(0, n - 20)

    let sawC = false
    let sawD = false
    for (let i = start; i < n; i++) {
        if (history[i].opponent === "C") sawC = true
        else sawD = true
    }
    if (!sawC || !sawD) return false

    for (let period = 2; period <= 6; period++) {
        let ok = true
        let checks = 0
        for (let i = start + period; i < n; i++) {
            checks++
            if (history[i].opponent !== history[i - period].opponent) {
                ok = false
                break
            }
        }
        if (!ok || checks < 8) continue

        let pureTFT = true
        for (let i = Math.max(1, start); i < n; i++) {
            if (history[i].opponent !== history[i - 1].you) {
                pureTFT = false
                break
            }
        }
        if (!pureTFT) return true
    }

    return false
}

function sparseSignature(history) {
    const n = history.length
    if (n === 3) {
        return (
            history[0].opponent === "C" &&
            history[1].opponent === "C" &&
            history[2].opponent === "D" &&
            history.every(r => r.you === "C")
        )
    }
    if (n === 5) {
        return (
            history[0].opponent === "C" &&
            history[1].opponent === "C" &&
            history[2].opponent === "C" &&
            history[3].opponent === "C" &&
            history[4].opponent === "D" &&
            history.every(r => r.you === "C")
        )
    }
    return false
}

function shouldProbe(memory, coopStreak, pC, pD, defRate) {
    if (memory.testFailures > MAX_FAILED_TESTS) return false
    if (memory.testRounds.length >= TEST_STREAKS.length) return false
    if (memory.testCooldown > 0) return false
    if (pC < COOPERATION_THRESHOLD) return false
    if (defRate > 0.28) return false
    if (pD > EXPLOIT_THRESHOLD) return false
    return coopStreak >= TEST_STREAKS[memory.testRounds.length]
}

function decide(history, memory) {
    const n = history.length
    if (n === 0) return ["C", createMemory()]

    memory = updateMemory(history, memory)
    const last = history[n - 1]
    const previous = n >= 2 ? history[n - 2] : null
    const lastOpp = last.opponent === "D" ? "D" : "C"

    if (history[0].opponent === "D" && history.every(r => r.you === "C")) {
        if (n <= 4 || lastOpp === "C") return ["C", memory]
    }

    if (!memory.cooperateBias && sparseSignature(history)) {
        memory.cooperateBias = true
        return ["C", memory]
    }

    if (memory.cooperateBias) {
        if (lastOpp === "D" && previous && previous.opponent === "D") {
            memory.cooperateBias = false
        } else {
            return ["C", memory]
        }
    }

    if (memory.opponentD === 0) return ["C", memory]

    if (isMostlyPeriodic(history)) return ["D", memory]

    const {
        pC,
        pD,
        samplesAfterD
    } = conditionalRates(history)
    const total = memory.opponentC + memory.opponentD
    const defRate = total ? memory.opponentD / total : 0
    const avgScore = memory.scoreTotal / n
    const noisy = n >= 18 && memory.flipNoise >= 10 && defRate > 0.2 && defRate < 0.8

    if (
        memory.hardMode ||
        (memory.opponentD >= 4 && defRate > 0.68) ||
        (n >= 18 && avgScore < 0.95) ||
        (noisy && defRate > 0.35) ||
        (memory.testFailures > MAX_FAILED_TESTS)
    ) {
        memory.hardMode = true
        if (memory.opponentC > memory.opponentD && defRate < 0.48) {
            memory.hardMode = false
        } else {
            if (
                memory.opponentC > 0 &&
                memory.olivesUsed < OLIVE_BRANCH_SCHEDULE.length &&
                memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olivesUsed]
            ) {
                memory.olivesUsed++
                return ["C", memory]
            }
            return ["D", memory]
        }
    }

    if (samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES && pD >= EXPLOIT_THRESHOLD && defRate < 0.35) {
        return ["D", memory]
    }

    if (pC >= COOPERATION_THRESHOLD) {
