function isUnconditionalPeriodic(history) {
    const n = history.length
    if (n < 12) return false
    const start = Math.max(0, n - 20)

    let sawC = false
    let sawD = false
    for (let i = start; i < n; i++) {
        if (history[i].opponent === C) sawC = true
        else sawD = true
    }
    if (!sawC || !sawD) return false

    for (let p = 2; p <= 6; p++) {
        let ok = true
        let checks = 0
        for (let i = start + p; i < n; i++) {
            checks++
            if (history[i].opponent !== history[i - p].opponent) {
                ok = false
                break
            }
        }
        if (!ok || checks < 8) continue

        let tftLike = true
        for (let i = Math.max(1, start); i < n; i++) {
            if (history[i].opponent !== history[i - 1].you) {
                tftLike = false
                break
            }
        }
        if (!tftLike) return true
    }

    return false
}

function sparsePrefix(history) {
    const n = history.length
    if (n === 3) {
        return (
            history[0].opponent === C &&
            history[1].opponent === C &&
            history[2].opponent === D &&
            history.every(r => r.you === C)
        )
    }
    if (n === 5) {
        return (
            history[0].opponent === C &&
            history[1].opponent === C &&
            history[2].opponent === C &&
            history[3].opponent === C &&
            history[4].opponent === D &&
            history.every(r => r.you === C)
        )
    }
    return false
}

function currentCoopStreak(history) {
    let s = 0
    for (let i = history.length - 1; i >= 0; i--) {
        if (history[i].you === C && history[i].opponent === C) s++
        else break
    }
    return s
}

function decide(history, memory) {
    const n = history.length
    if (n === 0) return [C, freshMemory()]

    memory = updateMemory(history, memory)

    const last = history[n - 1]
    const prev = n >= 2 ? history[n - 2] : null
    const oppLast = last.opponent === D ? D : C

    if (history[0].opponent === D && history.every(r => r.you === C)) {
        if (n <= 4 || oppLast === C) return [C, memory]
    }

    if (!memory.sparsePeace && sparsePrefix(history)) {
        memory.sparsePeace = true
        return [C, memory]
    }

    if (memory.sparsePeace) {
        if (oppLast === D && prev && prev.opponent === D) memory.sparsePeace = false
        else return [C, memory]
    }

    if (memory.opponentD === 0) return [C, memory]

    if (isUnconditionalPeriodic(history)) return [D, memory]

    const {
        pC,
        pD,
        samplesAfterD
    } = responseRates(history)
    const total = memory.opponentC + memory.opponentD
    const defRate = total ? memory.opponentD / total : 0
    const avg = memory.scoreTotal / n
    const noisy = n >= 18 && memory.flipNoise >= 10 && defRate > 0.2 && defRate < 0.8

    if (
        memory.hardMode ||
        (memory.opponentD >= 4 && defRate > HARD_DEFECT_RATE) ||
        (n >= 18 && avg < PANIC_AVG) ||
        (noisy && defRate > HARD_NOISY_DEFECT_RATE) ||
        (memory.testFailures > MAX_FAILED_TESTS)
    ) {
        memory.hardMode = true
        memory.exploitRun = 0
        if (memory.opponentC > memory.opponentD && defRate < 0.48) {
            memory.hardMode = false
        } else {
            if (
                memory.opponentC > 0 &&
                memory.olivesUsed < OLIVE_BRANCH_SCHEDULE.length &&
                memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olivesUsed]
            ) {
                memory.olivesUsed++
                return [C, memory]
            }
            return [D, memory]
        }
    }

    if (samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES && pD >= EXPLOIT_THRESHOLD && defRate < 0.42) {
        if (oppLast === C) {
            memory.exploitRun++
            if (memory.exploitRun % 7 === 0) return [C, memory]
            return [D, memory]
        }
        memory.exploitRun = 0
        return [D, memory]
    } else {
        memory.exploitRun = 0
    }

    if (pC >= COOPERATION_THRESHOLD) {
        const unprovokedD = oppLast === D && !(prev && prev.you === D)
        if (unprovokedD) return [D, memory]

        const cs = currentCoopStreak(history)
        if (
            oppLast === C &&
            memory.testFailures <= MAX_FAILED_TESTS &&
            memory.testRounds.length < TEST_STREAKS.length &&
            cs >= TEST_STREAKS[memory.testRounds.length] &&
            memory.testCooldown === 0 &&
            pD < 0.5 &&
            n - memory.lastProbeRound >= 10
        ) {
            memory.testRounds.push(n)
            memory.lastProbeRound = n
            memory.testCooldown = TEST_COOLDOWN
            return [D, memory]
        }

        if (memory.lastProbeRound === n - 1 && oppLast === D) memory.testFailures++

        if (memory.mutualDStreak >= DD_ESCAPE) return [C, memory]
        return [C, memory]
    }

    if (
        memory.opponentC > 0 &&
        memory.olivesUsed < OLIVE_BRANCH_SCHEDULE.length &&
        memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olivesUsed]
    ) {
        memory.olivesUsed++
        return [C, memory]
    }

    return [D, memory]
}

export default function bot(state) {
    let memory = state && state.memory && typeof state.memory === "object" ? state.memory : null
    try {
        const history = state && Array.isArray(state.history) ? state.history : []
        const [move, nextMemory] = decide(history, memory)
        return [move === C ? C : D, nextMemory]
    } catch {
        return [D, memory || freshMemory()]
    }
}

const WINDOW = 15
const COOPERATION_THRESHOLD = 0.7
const EXPLOIT_THRESHOLD = 0.4
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 20, 70]

function freshMemory() {
	return {
		seen: 0,
		opponentC: 0,
		opponentD: 0,
		mutualDStreak: 0,
		olives: 0,
	}
}

function rebuildMemory(history, previous) {
	const memory = freshMemory()
	memory.olives =
		previous && Number.isFinite(previous.olives)
			? Math.max(0, Math.floor(previous.olives))
			: 0

	for (let i = 0; i < history.length; i++) {
		const round = history[i]
		if (round.opponent === "D") memory.opponentD++
		else memory.opponentC++

		if (round.you === "D" && round.opponent === "D")
			memory.mutualDStreak++
		else memory.mutualDStreak = 0
	}

	memory.seen = history.length
	return memory
}

function updateMemory(history, memory) {
	const n = history.length

	// Under normal tournament execution, memory.seen is n - 1. Rebuild if
	// memory was malformed or became inconsistent instead of risking a crash.
	if (
		!memory ||
		typeof memory !== "object" ||
		memory.seen !== n - 1 ||
		!Number.isFinite(memory.opponentC) ||
		!Number.isFinite(memory.opponentD) ||
		!Number.isFinite(memory.mutualDStreak) ||
		!Number.isFinite(memory.olives)
	)
		return rebuildMemory(history, memory)

	const last = history[n - 1]
	if (last.opponent === "D") memory.opponentD++
	else memory.opponentC++

	if (last.you === "D" && last.opponent === "D")
		memory.mutualDStreak++
	else memory.mutualDStreak = 0

	memory.seen = n
	return memory
}

function smoothedRate(successes, samples) {
	// Jeffreys-style smoothing prevents tiny samples from producing certainty.
	return (successes + 0.5) / (samples + 1)
}

function responseRates(history) {
	let cooperateAfterC = 0
	let samplesAfterC = 0
	let cooperateAfterD = 0
	let samplesAfterD = 0
	const start = Math.max(1, history.length - WINDOW)

	// Their move at i can be a response to our move at i - 1.
	for (let i = start; i < history.length; i++) {
		const ourPreviousMove = history[i - 1].you
		const theirMove = history[i].opponent

		if (ourPreviousMove === "C") {
			samplesAfterC++
			if (theirMove === "C") cooperateAfterC++
		} else {
			samplesAfterD++
			if (theirMove === "C") cooperateAfterD++
		}
	}

	return {
		pC: smoothedRate(cooperateAfterC, samplesAfterC),
		pD: smoothedRate(cooperateAfterD, samplesAfterD),
		samplesAfterD,
	}
}

function isUnconditionalPeriodic(history) {
	const n = history.length
	const PERIOD_WINDOW = 20
	if (n < 12) return false

	const start = Math.max(0, n - PERIOD_WINDOW)
	let sawC = false
	let sawD = false

	for (let i = start; i < n; i++) {
		if (history[i].opponent === "C") sawC = true
		else sawD = true
	}
	if (!sawC || !sawD) return false

	for (let period = 2; period <= 6; period++) {
		let matches = true
		let comparisons = 0

		for (let i = start + period; i < n; i++) {
			comparisons++
			if (history[i].opponent !== history[i - period].opponent) {
				matches = false
				break
			}
		}

		if (!matches || comparisons < 8) continue

		// Do not call ordinary lag-one tit-for-tat an unconditional pattern.
		let explainedByTitForTat = true
		for (let i = Math.max(1, start); i < n; i++) {
			if (history[i].opponent !== history[i - 1].you) {
				explainedByTitForTat = false
				break
			}
		}

		if (!explainedByTitForTat) return true
	}

	return false
}

function decide(history, memory) {
	const n = history.length
	if (n === 0) return ["C", freshMemory()]

	memory = updateMemory(history, memory)
	const last = history[n - 1]
	const previous = n >= 2 ? history[n - 2] : null

	// Never disturb pristine cooperation. Probing cannot distinguish an
	// always-cooperator from a grudger without risking the whole relationship.
	if (memory.opponentD === 0) return ["C", memory]

	// Fixed alternators and other short unconditional cycles are best met by D.
	if (isUnconditionalPeriodic(history)) return ["D", memory]

	const { pC, pD, samplesAfterD } = responseRates(history)

	// If they have repeatedly cooperated after our D, continued defection has
	// demonstrated positive value. Re-evaluate every turn so retaliation exits
	// this behavior instead of locking us into it forever.
	if (
		samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES &&
		pD >= EXPLOIT_THRESHOLD
	)
		return ["D", memory]

	// A responsive opponent is valuable. Punish only an unprovoked D. If their
	// D followed our D, cooperate to break a retaliation loop (contrition).
	if (pC >= COOPERATION_THRESHOLD) {
		const theirDWasProvoked =
			last.opponent === "D" &&
			previous !== null &&
			previous.you === "D"

		if (last.opponent === "D" && !theirDWasProvoked)
			return ["D", memory]

		return ["C", memory]
	}

	// In an unproductive DD loop, occasionally test for recovery only if this
	// opponent has cooperated before. Never donate points to a pure defector.
	if (
		memory.opponentC > 0 &&
		memory.olives < OLIVE_BRANCH_SCHEDULE.length &&
		memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olives]
	) {
		memory.olives++
		return ["C", memory]
	}

	return ["D", memory]
}

export default function bot(state) {
	let memory =
		state && state.memory && typeof state.memory === "object"
			? state.memory
			: null

	try {
		const history =
			state && Array.isArray(state.history) ? state.history : []
		const [move, nextMemory] = decide(history, memory)
		return [move === "C" ? "C" : "D", nextMemory]
	} catch {
		// A conservative valid move is much better than forfeiting the battle.
		return ["D", memory ?? freshMemory()]
	}
}

export default function bot(state) {
  const C = "C", D = "D";
  const CFG = {
    window: 30,          // stable conditional rates
    tolerate: 2,         // much shorter opening absorption
    coopFloor: 0.60,     // P(they C | we C) below which we become hard
    exploitFloor: 0.70,  // P(they C | we D) above which we exploit
    olives: [4, 12, 30, 70, 150], // earlier first olive, spaced out
    maxSucker: 6,        // allow a few unpunished defections
    maxExits: 3          // multiple chances to leave hard mode
  };
  let hist = null;

  try {
    const raw = state && Array.isArray(state.history) ? state.history : [];
    const n = raw.length;
    hist = raw;
    const m = loadMem(state ? state.memory : null);
    if (n === 0) return out(C, m);

    /* ---------- single statistics pass ---------- */
    let oppD = 0, myD = 0, cAfterC = 0, nAfterC = 0, cAfterD = 0, nAfterD = 0;
    let sucker = 0, recPts = 0, recN = 0;
    const w0 = n - CFG.window > 0 ? n - CFG.window : 0;
    const s0 = n - 10 > 0 ? n - 10 : 0;
    for (let i = 0; i < n; i++) {
      const o = opp(i), y = you(i);
      if (o === D) oppD++;
      if (y === D) myD++;
      if (i >= w0 && i > 0) {
        if (you(i - 1) === C) { nAfterC++; if (o === C) cAfterC++; }
        else { nAfterD++; if (o === C) cAfterD++; }
      }
