          return out(C, m);
        }
        return out(D, m);
      }
      if (prevYou === D) return out(C, m);
      return out(D, m);
    }
    return out(C, m);

  } catch (err) {
    try {
      const hs = state && state.history;
      const l = hs && hs.length ? hs[hs.length - 1] : null;
      const v = l && l.opponent;
      return [typeof v === "string" && v.charAt(0).toUpperCase() === "D" ? "D" : "C",
              (state && state.memory) || null];
    } catch (e2) { return ["C", null]; }
  }

  function isPeriodic(n) {
    if (n < 12) return false;
    const from = n - 20 > 0 ? n - 20 : 0;
    let sawC = false, sawD = false;
    for (let i = from; i < n; i++) { if (opp(i) === C) sawC = true; else sawD = true; }
    if (!sawC || !sawD) return false;
    for (let p = 2; p <= 6; p++) {
      let ok = true, checks = 0;
      for (let i = from + p; i < n; i++) {
        checks++;
        if (opp(i) !== opp(i - p)) { ok = false; break; }
      }
      if (!ok || checks < 8) continue;
      for (let i = from > 1 ? from : 1; i < n; i++) if (opp(i) !== you(i - 1)) return true;
    }
    return false;
  }

  function mv(v) {
    if (v === D) return D;
    if (typeof v === "string" && v.length && v.charAt(0).toUpperCase() === "D") return D;
    return C;
  }
  function you(i) { const r = hist[i]; return r ? mv(r.you) : C; }
  function opp(i) { const r = hist[i]; return r ? mv(r.opponent) : C; }

  function loadMem(raw) {
    const base = { olive: 0, hard: 0, unresp: 0, exits: 0, oliveAt: -1 };
    if (raw && typeof raw === "object") {
      for (const k of ["olive", "hard", "unresp", "exits", "oliveAt"]) {
        const v = raw[k];
        if (typeof v === "number" && isFinite(v)) base[k] = v;
      }
      if (base.olive < 0) base.olive = 0;
    }
    return base;
  }
  function out(move, m) { return [move === D ? D : C, m]; }
}

export default function bot({ history, memory }) {
  try {
    const C = "C", D = "D"
    if (!memory || memory.v !== 600) {
      memory = { v: 600, oppC: 0, oppD: 0, aC: [0, 0], aD: [0, 0],
        dStreak: 0, cStreak: 0, punish: 0, calm: 0,
        antiFarm: false, maybeCorn: false, cornLock: false,
        periodD: false, periodCheck: -20, dWindow: [0,0,0,0,0,0,0,0] }
    }
    const m = memory
    const n = history.length
    if (n === 0) return [C, m]
    if (n === 1) return [C, m]
    if (n === 2) {
      // corn/praesidium fingerprint: their r1=C, r2=D → our C,C,D locks them to cooperation
      if (history[0].opponent === C && history[1].opponent === D) { m.maybeCorn = true; return [D, m] }
      return [C, m]
    }
    if (n === 3 && m.maybeCorn && history[2].opponent === C) m.cornLock = true

    const last = history[n - 1]
    const myPrev = history[n - 2].you
    if (last.opponent === C) { m.oppC++; m.cStreak++; m.dStreak = 0 }
    else { m.oppD++; m.dStreak++; m.cStreak = 0 }
    // 8-round D-window (goat-style radar)
    m.dWindow.push(last.opponent === D ? 1 : 0)
    if (m.dWindow.length > 8) m.dWindow.shift()
    const dIn8 = m.dWindow.reduce((a, b) => a + b, 0)
    if (myPrev === C) { m.aC[1]++; if (last.opponent === C) m.aC[0]++ }
    else { m.aD[1]++; if (last.opponent === C) m.aD[0]++ }

    // ---- PERIODICITY ----
    if (n - m.periodCheck >= 14 && n >= 20) {
      m.periodCheck = n
      const L = Math.min(28, n), from = n - L
      const dR = history.slice(from, n).filter(r => r.opponent === D).length / L
      if (dR > 0.1 && dR < 0.9) {
        let bestP = 0
        for (let p = 2; p <= 8; p++) {
          let ok = true, checks = 0
          for (let i = from + p; i < n; i++) { checks++; if (history[i].opponent !== history[i - p].opponent) { ok = false; break } }
          if (ok && checks >= 12) { bestP = p; break }
        }
        if (bestP > 0) {
          let reactive = 0, tot = 0
          for (let i = Math.max(1, from); i < n; i++) { tot++; if (history[i].opponent === history[i - 1].you) reactive++ }
          if (tot > 0 && reactive / tot > 0.8) bestP = 0
        }
        m.periodD = bestP > 0
      }
    }

    // ---- HARD MODES ----
    // pure defector: D-lock with rare reform probes
    if (m.oppC === 0 && n >= 4) { if (n % 30 === 29) return [C, m]; return [D, m] }
    // periodic → D
    if (m.periodD && m.oppD / n > 0.15) return [n % 20 === 19 ? C : D, m]
    // corn/praesidium farm
    if (m.cornLock) {
      if (n >= 8 && history.slice(Math.max(4, n - 6), n).every(r => r.opponent === D)) m.cornLock = false
      else return [n % 12 === 11 ? C : D, m]
    }
    // anti-correlated (reverse-TFT family): farm with all-D
    if (n >= 10 && m.aC[1] >= 5 && m.aD[1] >= 3) {
      const pC = m.aC[0] / m.aC[1], pD = m.aD[0] / m.aD[1]
      if (pC <= 0.3 && pD >= 0.7) m.antiFarm = true
      else if (m.antiFarm && (pD < 0.5 || pC > 0.5)) m.antiFarm = false
    }
    if (m.antiFarm) return [n % 13 === 12 ? C : D, m]

    // ---- CONDITIONAL RESPONSES ----
    const pCafterC = m.aC[1] >= 6 ? m.aC[0] / m.aC[1] : null
    const pCafterD = m.aD[1] >= 4 ? m.aD[0] / m.aD[1] : null
    // TF2T-forgiver: alternate
    if (pCafterC !== null && pCafterD !== null && pCafterC >= 0.75 && pCafterD >= 0.55 && m.oppD / n < 0.35) {
      if (m.dStreak === 0) return [n % 2 === 1 ? D : C, m]
      return [C, m]
    }
    // random → D (rare keeps)
    if (n >= 16 && pCafterC !== null && pCafterD !== null && Math.abs(pCafterC - pCafterD) < 0.22 && m.oppD / n > 0.18 && m.oppD / n < 0.85) {
      return [n % 20 === 19 ? C : D, m]
    }
    if (n >= 12 && m.oppD / n > 0.3 && m.oppD / n < 0.8 && m.dStreak < 3 && m.cStreak < 5 && pCafterC === null) {
      return [D, m]
    }
    // extortioner / non-cooperative responsive → D (F2: threshold 0.45)
    if (n >= 25 && m.oppD / n > 0.45) return [n % 20 === 19 ? C : D, m]

    // ---- CORE: probe-tolerant gradual (F1) ----
    if (m.punish > 0) { m.punish--; return [D, m] }
    if (m.calm > 0) { m.calm--; return [C, m] }
    if (last.opponent === D) {
      if (myPrev === D) { m.calm = 1; return [C, m] } // contrition
      if (dIn8 >= 2 || m.oppD / n > 0.25) {
        // repeated/reckless defection: gradual punishment
        m.punish = Math.min(m.oppD, 3) - 1
        m.calm = 2
        return [D, m]
      }
      // F1: isolated probe → single D + calm (pumpkin-safe)
      m.calm = 2
      return [D, m]
    }
    return [C, m]
  } catch (e) { return ["C", null] }
}

export default function bot(state) {
  const C = "C", D = "D";
  const CFG = {
    window: 30,
    tolerate: 3,          // Extended to absorb firstbornv3.2 (3 D opening)
    coopFloor: 0.60,
    exploitFloor: 0.70,
    olives: [6, 16, 36, 80],
    maxSucker: 5,
    maxExits: 3
  };
  let hist = null;

  try {
    const raw = state && Array.isArray(state.history) ? state.history : [];
    const n = raw.length;
    hist = raw;
    const m = loadMem(state ? state.memory : null);

    // Round 0: Always start with Cooperation
    if (n === 0) return out(C, m);

    /* ---------- 1. Anti-Detective & Sherlock Holmes Detection ---------- */
    // Sherlock Holmes plays C, D, C on rounds 0, 1, 2
    if (n === 1 && opp(0) === C) return out(C, m);
    if (n === 2 && opp(0) === C && opp(1) === D) {
      m.isSherlock = 1;
      return out(D, m); // Retaliate to force Sherlock into REACTIF mode
    }

    /* ---------- single statistics pass ---------- */
    let oppD = 0, myD = 0, cAfterC = 0, nAfterC = 0, cAfterD = 0, nAfterD = 0;
    let sucker = 0, recPts = 0, recN = 0;
    const w0 = n - CFG.window > 0 ? n - CFG.window : 0;
    const s0 = n - 10 > 0 ? n - 10 : 0;

    for (let i = 0; i < n; i++) {
      const o = opp(i), y = you(i);
      if (o === D) oppD++;
      if (y === D) myD++;
      if (i >= w0 && i > 0) {
        if (you(i - 1) === C) { nAfterC++; if (o === C) cAfterC++; }
        else { nAfterD++; if (o === C) cAfterD++; }
      }
      if (i >= s0) {
        if (y === C && o === D) sucker++;
        recN++; recPts += y === C ? (o === C ? 2 : 0) : (o === C ? 3 : 1);
      }
    }

    let mutualD = 0;
    for (let i = n - 1; i >= 0 && you(i) === D && opp(i) === D; i--) mutualD++;
    let mutualC = 0;
    for (let i = n - 1; i >= 0 && you(i) === C && opp(i) === C; i--) mutualC++;

    if (mutualC >= 6) m.olive = 0; // Restore olive budget when peaceful

    const pC = (cAfterC + 0.5) / (nAfterC + 1);
    const pD = (cAfterD + 0.5) / (nAfterD + 1);
    const oppRate = oppD / n;
    const lastOpp = opp(n - 1), lastYou = you(n - 1);
    const prevYou = n >= 2 ? you(n - 2) : C;

    /* ---------- 2. Late-Game Betrayal Detection (defecthalfv2 Counter) ---------- */
    // Detect bots that played friendly for 20+ rounds then permanently switched to Defect
    if (n > 25 && m.lateBetrayal !== 1) {
      let earlyCoop = 0;
      for (let i = 0; i < 20; i++) if (opp(i) === C) earlyCoop++;
      const lateStreakD = (opp(n - 1) === D && opp(n - 2) === D && opp(n - 3) === D);
      if (earlyCoop >= 16 && lateStreakD) {
        m.lateBetrayal = 1;
      }
    }
    if (m.lateBetrayal === 1) return out(D, m); // Cancel olive branches permanently

    /* ---------- 3. Pure Defector Fast-Cutoff ---------- */
    if (oppD === n && n >= CFG.tolerate) return out(D, m);

    /* ---------- 4. Absorb Hostile Openings (firstbornv3.2 Counter) ---------- */
    // Handles up to 3 consecutive opening defections if opponent normalizes
    if (n <= 4 && oppD === n && myD < n - 1) {
      return out(C, m); // Offer grace period for rounds 1-3
    }

    /* ---------- 5. Clean Relationship Protection ---------- */
    if (oppD === 0) return out(C, m);

    /* ---------- 6. Periodic Pattern Exploitation ---------- */
    if (isPeriodic(n)) return out(D, m);

    /* ---------- 7. Exploit Unpunished Defection ---------- */
    if (nAfterD >= 3 && pD >= CFG.exploitFloor && oppRate < 0.35 && lastYou === C) {
      return out(D, m);
    }

    /* ---------- 8. Hostile / Parasitic Classification ---------- */
    const unresponsive = nAfterC >= 4 && nAfterD >= 3 && Math.abs(pC - pD) < 0.25 && oppRate > 0.2;
    const parasitic = (nAfterC >= 4 && pC < CFG.coopFloor) || 
                      (n >= 12 && sucker >= CFG.maxSucker) || 
                      (n >= 10 && oppRate > 0.85);

    if (unresponsive || parasitic) {
      m.hard = 1;
      if (unresponsive) m.unresp = 1;
    }

    /* ---------- 9. Hard Mode Execution ---------- */
    if (m.hard) {
      if (m.oliveAt >= 0) {
        if (n < m.oliveAt + 2) return out(C, m);
        const taken = opp(m.oliveAt + 1) === C;
        m.oliveAt = -1;
        if (taken && m.exits < CFG.maxExits) {
          m.exits++; m.hard = 0; m.unresp = 0; m.olive = 0;
          return out(C, m);
        }
      }
      const need = 3;
      if (m.exits < CFG.maxExits && n >= need) {
        let allC = true;
        for (let i = n - need; i < n; i++) if (opp(i) !== C) { allC = false; break; }
        if (allC) {
          m.exits++; m.hard = 0; m.unresp = 0; m.olive = 0;
          return out(C, m);
        }
      }
      if (!m.unresp && m.exits < CFG.maxExits && oppD < n &&
          m.olive < CFG.olives.length && mutualD >= CFG.olives[m.olive]) {
        m.olive++; m.oliveAt = n;
        return out(C, m);
      }
      return out(D, m);
    }

    /* ---------- 10. Strict Contrite Tit-For-Tat Core ---------- */
    if (lastOpp === D) {
      if (lastYou === D) {
        if (m.olive < CFG.olives.length && mutualD >= CFG.olives[m.olive]) {
          m.olive++;
          return out(C, m);
        }
        return out(D, m);
      }
      if (prevYou === D) return out(C, m); // Contrite response
      return out(D, m);
    }
    return out(C, m);

  } catch (err) {
    try {
      const hs = state && state.history;
      const l = hs && hs.length ? hs[hs.length - 1] : null;
      const v = l && l.opponent;
      return [typeof v === "string" && v.charAt(0).toUpperCase() === "D" ? "D" : "C",
              (state && state.memory) || null];
    } catch (e2) { return ["C", null]; }
  }

  /* Helper functions */
  function isPeriodic(n) {
    if (n < 12) return false;
    const from = n - 20 > 0 ? n - 20 : 0;
    let sawC = false, sawD = false;
    for (let i = from; i < n; i++) { if (opp(i) === C) sawC = true; else sawD = true; }
    if (!sawC || !sawD) return false;
    for (let p = 2; p <= 6; p++) {
      let ok = true, checks = 0;
      for (let i = from + p; i < n; i++) {
        checks++;
        if (opp(i) !== opp(i - p)) { ok = false; break; }
      }
      if (!ok || checks < 8) continue;
      for (let i = from > 1 ? from : 1; i < n; i++) if (opp(i) !== you(i - 1)) return true;
    }
    return false;
  }

  function mv(v) {
    if (v === D) return D;
    if (typeof v === "string" && v.length && v.charAt(0).toUpperCase() === "D") return D;
    return C;
  }
  function you(i) { const r = hist[i]; return r ? mv(r.you) : C; }
  function opp(i) { const r = hist[i]; return r ? mv(r.opponent) : C; }

  function loadMem(raw) {
    const base = { olive: 0, hard: 0, unresp: 0, exits: 0, oliveAt: -1, lateBetrayal: 0, isSherlock: 0 };
    if (raw && typeof raw === "object") {
      for (const k of ["olive", "hard", "unresp", "exits", "oliveAt", "lateBetrayal", "isSherlock"]) {
        const v = raw[k];
        if (typeof v === "number" && isFinite(v)) base[k] = v;
      }
      if (base.olive < 0) base.olive = 0;
    }
    return base;
  }
  function out(move, m) { return [move === D ? D : C, m]; }
}

export default function bot({ history, memory }) {
  const C = "C", D = "D";

  const freshMemory = () => ({
    oppC: 0, oppD: 0,
    recent: [],
    oppDefStreak: 0, oppCoopStreak: 0,
    ourScoreSum: 0,
    everWeDefected: false,
    logp: [0, 0, 0, 0, 0], // AllC, AllD, TFT, Pavlov, Grim
    hardLock: false,
    exploitLock: false,
    suppressRetaliation: 0,
    lastProbe: 0,
  });

  try {
    const n = history.length;

    if (!memory || typeof memory !== "object" || !Array.isArray(memory.logp)) {
      memory = freshMemory();
    }

    if (n === 0) return [C, memory]; // always open with cooperation

    const last = history[n - 1];
    const myLast = last.you === D ? D : C;
    const oppLast = last.opponent === D ? D : C;

    // --- running stats ---
    if (oppLast === C) {
      memory.oppC++; memory.oppCoopStreak++; memory.oppDefStreak = 0;
    } else {
      memory.oppD++; memory.oppDefStreak++; memory.oppCoopStreak = 0;
    }
    memory.recent.push(oppLast);
    if (memory.recent.length > 10) memory.recent.shift();

    const payoff =
      myLast === C && oppLast === C ? 2 :
      myLast === D && oppLast === C ? 3 :
      myLast === C && oppLast === D ? 0 : 1;
    memory.ourScoreSum += payoff;

    // --- Bayesian opponent classification (incremental, O(1)/round) ---
    const eps = 0.05;
    if (n >= 2) {
      const prev = history[n - 2];
      const prevYou = prev.you === D ? D : C;
      const prevOpp = prev.opponent === D ? D : C;

      const predAllC = C;
      const predAllD = D;
      const predTFT = prevYou;
      const predPavlov = prevYou === prevOpp ? prevOpp : (prevOpp === C ? D : C);
      const predGrim = memory.everWeDefected ? D : C;

      const preds = [predAllC, predAllD, predTFT, predPavlov, predGrim];
      for (let i = 0; i < 5; i++) {
        const p = preds[i] === oppLast ? (1 - eps) : eps;
        memory.logp[i] += Math.log(p);
      }
    }
    memory.everWeDefected = memory.everWeDefected || (myLast === D);

    // --- posterior over opponent archetype ---
    const maxLp = Math.max(...memory.logp);
    const exps = memory.logp.map(x => Math.exp(x - maxLp));
    const sumExp = exps.reduce((a, b) => a + b, 0);
    const post = exps.map(x => x / sumExp);
    const [pAllC, pAllD, , , pGrim] = post;
    const pHard = pAllD + pGrim;
    const pMax = Math.max(...post);

    const totalOppMoves = memory.oppC + memory.oppD;
    const oppDefectRate = totalOppMoves ? memory.oppD / totalOppMoves : 0;
    const avgPayoff = memory.ourScoreSum / n;
    const looksRandom = n >= 20 && pMax < 0.4 && oppDefectRate > 0.25 && oppDefectRate < 0.75;

    // 1. Hard-defector backstop (fast trigger on streaks, slower on stats)
    if (
      memory.oppDefStreak >= 3 ||
      (totalOppMoves >= 5 && oppDefectRate > 0.7) ||
      (n >= 4 && pHard > 0.75) ||
      looksRandom
    ) {
      memory.hardLock = true;
    }
    if (memory.hardLock) {
      if (memory.oppCoopStreak >= 3) memory.hardLock = false; // let them redeem
      else return [D, memory];
    }

    // 2. Exploit lock — confirmed non-retaliatory cooperator, harvest 3/round
    if (memory.exploitLock) {
      if (oppLast === D) memory.exploitLock = false; // they finally punched back
      else return [D, memory];
    }
    if (!memory.exploitLock && n >= 8 && pAllC > 0.8 && memory.oppDefStreak === 0 && memory.everWeDefected) {
      memory.exploitLock = true;
      return [D, memory];
    }

    // 3. Payoff safety net — bail if a strategy is clearly losing us value
    if (n >= 20 && avgPayoff < 0.9) {
      memory.hardLock = true;
      return [D, memory];
    }

    // 4. Deliberate probe to classify ambiguous / never-tested opponents
    const dueForProbe =
      oppLast === C && (n === 3 || (pMax < 0.55 && (n - memory.lastProbe) > 12));
    if (dueForProbe) {
      memory.lastProbe = n;
      memory.suppressRetaliation = 1; // pre-forgive their justified response
      return [D, memory];
    }

    // 5. Generous tit-for-tat: retaliate exactly once, then force a resync
    let move;
    if (oppLast === D) {
      if (memory.suppressRetaliation > 0 && pHard < 0.6) {
        memory.suppressRetaliation--;
        move = C;
      } else {
        move = D;
        memory.suppressRetaliation = pHard < 0.6 ? 1 : 0;
      }
    } else {
      move = C;
    }

    return [move, memory];
  } catch (e) {
    // Never forfeit on an exception — mirror opponent, or cooperate if no data.
    const safeMem = {
      oppC: 0, oppD: 0, recent: [], oppDefStreak: 0, oppCoopStreak: 0,
      ourScoreSum: 0, everWeDefected: false, logp: [0, 0, 0, 0, 0],
      hardLock: false, exploitLock: false, suppressRetaliation: 0, lastProbe: 0,
    };
    if (history && history.length > 0) {
      const opp = history[history.length - 1].opponent === "D" ? "D" : "C";
      return [opp, safeMem];
    }
    return ["C", safeMem];
  }
}

export default function bot({ history, memory }) {
  const n = history.length
  const last = history[n - 1]

  if (n === 0) return ["C", null]

  if (memory == null) {
    memory = { mode: "observe" }
  }

  if (memory.mode === "observe") {
    if (n >= 5) {
      const opening = history.slice(0, 5).map(round => round.opponent).join("")

      if (opening === "CDCCC") memory.mode = "exploit"
      else if (opening === "DDDDD") memory.mode = "hard"
      else memory.mode = "friend"
    } else {

      if (last.opponent === "C") return ["C", memory]
      if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
      return ["D", memory]
    }
  }

  if (memory.mode === "exploit" || memory.mode === "hard") {
    return ["D", memory]
  }

  if (n >= 10) {
    const recent = history.slice(-8)
    const defections = recent.reduce(
      (count, round) => count + (round.opponent === "D" ? 1 : 0),
      0,
    )
    if (defections >= 2) {
      memory.mode = "hard"
      return ["D", memory]
    }
  }

  if (last.opponent === "C") return ["C", memory]
  if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
  if (last.you === "D") return ["C", memory]
  return ["D", memory]
}

const TEST=8, NEED=2

export default function bot({history:h=[],memory:m}){
	m=m&&typeof m=="object"?m:{d:0,b:0}
	m.d=Number.isFinite(m.d)?m.d:0
	m.b=Number.isFinite(m.b)?m.b:0

	if(!h.length)return["C",m]

	const x=h.at(-1).opponent

	if(x=="D"){
		m.d++
		if(m.d>=NEED)m.b=1
	}else{
		m.d=0
	}

	if(m.b)return["D",m]

	if(m.d>=TEST)
		return["C",(m.d=0,m)]

	return[x=="C"?"C":"D",m]
}

